#!/bin/bash
#SBATCH --job-name=CPS           ## 作业名称
#SBATCH --nodes=1               
#SBATCH --cpus-per-task=160       ## CPU核数         
#SBATCH --output=out_%j.log       ## 输出文件
#SBATCH --error=err_%j.log        ## 错误文件
#SBATCH --exclusive
#SBATCH --partition=second

